INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'system', 'n.', '/ˈsɪstəm/', '体系;系统;制度', 'The Chinese writing system has lasted thousands of years.', '汉字书写系统已延续数千年。', 'Languages Around the World', 1, 0, 'senior', 'wordlist', 'required1', 'U5', 'the writing system', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'character', 'n.', '/ˈkærəktə(r)/', '文字;符号;角色;品质;特点', 'Some ancient symbols can still be seen in today''s characters.', '一些古老的符号至今仍能在汉字中看到。', 'Languages Around the World', 2, 0, 'senior', 'wordlist', 'required1', 'U5', 'Chinese characters', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'calligraphy', 'n.', '/kəˈlɪɡrəfi/', '书法;书法艺术', 'Chinese calligraphy is an important part of the culture.', '中国书法是文化的重要组成部分。', 'Languages Around the World', 3, 0, 'senior', 'wordlist', 'required1', 'U5', 'Chinese calligraphy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'civilisation', 'n.', '/ˌsɪvəlaɪˈzeɪʃn/', '文明;文明世界', 'China is known for its ancient civilisation.', '中国以其古老的文明而闻名。', 'Languages Around the World', 4, 0, 'senior', 'wordlist', 'required1', 'U5', 'ancient civilisation', '美式拼 civilization;美音 /ˌsɪvələˈzeɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dynasty', 'n.', '/ˈdɪnəsti/', '王朝;朝代', 'The writing system developed during the Shang Dynasty.', '书写系统在商朝得到发展。', 'Languages Around the World', 5, 0, 'senior', 'wordlist', 'required1', 'U5', 'the Qin Dynasty', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'symbol', 'n.', '/ˈsɪmbl/', '符号;象征', 'Ancient people carved symbols onto bones and shells.', '古人把符号刻在骨头和龟甲上。', 'Languages Around the World', 6, 0, 'senior', 'wordlist', 'required1', 'U5', 'carve symbols', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'carve', 'v.', '/kɑːv/', '雕刻', 'The symbols were carved by ancient Chinese people.', '这些符号是古代中国人刻上去的。', 'Languages Around the World', 7, 0, 'senior', 'wordlist', 'required1', 'U5', 'carve onto bone', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'bone', 'n.', '/bəʊn/', '骨头;骨', 'Early writing was done on animal bones.', '早期文字写在动物骨头上。', 'Languages Around the World', 8, 0, 'senior', 'wordlist', 'required1', 'U5', 'animal bones', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'shell', 'n.', '/ʃel/', '壳;贝壳', 'Symbols were carved onto bones and shells.', '符号被刻在骨头和龟甲上。', 'Languages Around the World', 9, 0, 'senior', 'wordlist', 'required1', 'U5', 'bones and shells', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dialect', 'n.', '/ˈdaɪəlekt/', '方言;地方话', 'People who speak different dialects can still read the same characters.', '说不同方言的人仍能读懂同样的汉字。', 'Languages Around the World', 10, 0, 'senior', 'wordlist', 'required1', 'U5', 'different dialects', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'means', 'n.', '/miːnz/', '方式;方法;途径', 'Writing is a means by which the past connects with the present.', '文字是连接过去与现在的一种方式。', 'Languages Around the World', 11, 0, 'senior', 'wordlist', 'required1', 'U5', 'a means of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'classic', 'adj./n.', '/ˈklæsɪk/', '经典的;典型的;经典作品', 'People today can read the classic works of the past.', '今天的人能读懂过去的经典作品。', 'Languages Around the World', 12, 0, 'senior', 'wordlist', 'required1', 'U5', 'classic works', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'regard', 'v./n.', '/rɪˈɡɑːd/', '把……视为;尊重;关注', 'Chinese people hold their writing system in high regard.', '中国人非常看重自己的书写系统。', 'Languages Around the World', 13, 0, 'senior', 'wordlist', 'required1', 'U5', 'high regard', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unify', 'v.', '/ˈjuːnɪfaɪ/', '统一;(使)成一体', 'Emperor Qinshihuang unified the writing system.', '秦始皇统一了文字。', 'Languages Around the World', 14, 0, 'senior', 'wordlist', 'required1', 'U5', 'unify the country', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'variety', 'n.', '/vəˈraɪəti/', '变体;多样化;种类', 'Over time, many varieties of characters appeared.', '随着时间推移,出现了许多文字变体。', 'Languages Around the World', 15, 0, 'senior', 'wordlist', 'required1', 'U5', 'a variety of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'major', 'adj.', '/ˈmeɪdʒə(r)/', '主要的;重要的;大的', 'The writing system was a major factor in uniting the people.', '书写系统是团结人民的一个主要因素。', 'Languages Around the World', 16, 0, 'senior', 'wordlist', 'required1', 'U5', 'a major factor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'factor', 'n.', '/ˈfæktə(r)/', '因素;要素', 'Many factors helped the culture survive.', '许多因素帮助这一文化得以延续。', 'Languages Around the World', 17, 0, 'senior', 'wordlist', 'required1', 'U5', 'an important factor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'despite', 'prep.', '/dɪˈspaɪt/', '尽管;即使', 'The civilisation continued despite many ups and downs.', '尽管历经诸多起伏,这一文明仍延续下来。', 'Languages Around the World', 18, 0, 'senior', 'wordlist', 'required1', 'U5', 'despite the difficulties', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'develop', 'v.', '/dɪˈveləp/', '发展;开发;成长', 'The symbols developed into a writing system.', '这些符号发展成了一套书写系统。', 'Languages Around the World', 19, 0, 'senior', 'wordlist', 'required1', 'U5', 'develop into', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'modern', 'adj.', '/ˈmɒdn/', '现代的;近代的', 'The ancient civilisation has continued into modern times.', '这一古老文明一直延续到现代。', 'Languages Around the World', 20, 0, 'senior', 'wordlist', 'required1', 'U5', 'modern times', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ancient', 'adj.', '/ˈeɪnʃənt/', '古代的;古老的', 'People in modern times can read ancient writing.', '现代人能读懂古代的文字。', 'Languages Around the World', 21, 0, 'senior', 'wordlist', 'required1', 'U5', 'ancient symbols', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'communicate', 'v.', '/kəˈmjuːnɪkeɪt/', '交流;沟通;传达', 'People across China can communicate in writing.', '中国各地的人都能用文字交流。', 'Languages Around the World', 22, 0, 'senior', 'wordlist', 'required1', 'U5', 'communicate in writing', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'native', 'adj./n.', '/ˈneɪtɪv/', '本地的;出生地的;本地人', 'Chinese has the most native speakers in the world.', '汉语是世界上母语使用者最多的语言。', 'Languages Around the World', 23, 0, 'senior', 'wordlist', 'required1', 'U5', 'native speakers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'global', 'adj.', '/ˈɡləʊbl/', '全球的;全世界的', 'China plays a greater role in global affairs today.', '如今中国在全球事务中发挥着更大作用。', 'Languages Around the World', 24, 0, 'senior', 'wordlist', 'required1', 'U5', 'global affairs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'billion', 'num.', '/ˈbɪljən/', '十亿', 'These languages are spoken by billions of people.', '这些语言被数十亿人使用。', 'Languages Around the World', 25, 0, 'senior', 'wordlist', 'required1', 'U5', 'billions of people', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'attitude', 'n.', '/ˈætɪtjuːd/', '态度;看法', 'My attitude towards language learning changed over time.', '我对语言学习的态度逐渐改变了。', 'Languages Around the World', 26, 0, 'senior', 'wordlist', 'required1', 'U5', 'a positive attitude', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'struggle', 'n./v.', '/ˈstrʌɡl/', '斗争;奋斗;艰难地做', 'At first, studying German was a real struggle for me.', '起初,学德语对我来说很吃力。', 'Languages Around the World', 27, 0, 'senior', 'wordlist', 'required1', 'U5', 'a struggle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tongue', 'n.', '/tʌŋ/', '舌头;语言', 'The new words felt strange on my tongue.', '这些新词读起来很别扭。', 'Languages Around the World', 28, 0, 'senior', 'wordlist', 'required1', 'U5', 'on my tongue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'appreciate', 'v.', '/əˈpriːʃieɪt/', '欣赏;重视;感激;领会', 'Students begin to appreciate China''s culture through the language.', '学生们通过这门语言开始欣赏中国文化。', 'Languages Around the World', 29, 0, 'senior', 'wordlist', 'required1', 'U5', 'appreciate the culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'specific', 'adj.', '/spəˈsɪfɪk/', '特定的;明确的;具体的', 'Scan the text to find specific information such as dates.', '略读课文,寻找日期等具体信息。', 'Languages Around the World', 30, 0, 'senior', 'wordlist', 'required1', 'U5', 'specific information', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reference', 'n.', '/ˈrefrəns/', '指称关系;参考;提及', 'Pronouns refer to something mentioned earlier in the text.', '代词指代文中前面提到的事物。', 'Languages Around the World', 31, 0, 'senior', 'wordlist', 'required1', 'U5', 'make a reference to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'relate', 'v.', '/rɪˈleɪt/', '联系;讲述;相关', 'Each sentence should relate to the main idea.', '每个句子都应与中心思想相关。', 'Languages Around the World', 32, 0, 'senior', 'wordlist', 'required1', 'U5', 'relate to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gap', 'n.', '/ɡæp/', '差距;间隔;缺口', 'A few kind words can bridge the gap between strangers.', '几句友善的话能拉近陌生人之间的距离。', 'Languages Around the World', 33, 0, 'senior', 'wordlist', 'required1', 'U5', 'bridge the gap', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'increase', 'v.', '/ɪnˈkriːs/', '增加;增长', 'An increasing number of students are learning Chinese.', '越来越多的学生在学习汉语。', 'Languages Around the World', 34, 0, 'senior', 'wordlist', 'required1', 'U5', 'an increasing number', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'spell', 'v.', '/spel/', '拼写;拼出', 'English words are spelt according to how they sound.', '英语单词按发音拼写。', 'Languages Around the World', 35, 0, 'senior', 'wordlist', 'required1', 'U5', 'spell a word', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'advice', 'n.', '/ədˈvaɪs/', '建议;忠告', 'Wang Le asked the forum for advice on listening.', '王乐在论坛上请教听力方面的建议。', 'Languages Around the World', 36, 0, 'senior', 'wordlist', 'required1', 'U5', 'give advice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'polite', 'adj.', '/pəˈlaɪt/', '礼貌的;客气的', 'It is hard to know how to be polite in another language.', '在另一种语言里很难掌握如何表达礼貌。', 'Languages Around the World', 37, 0, 'senior', 'wordlist', 'required1', 'U5', 'be polite', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'request', 'n./v.', '/rɪˈkwest/', '请求;要求', '"Could you open the window?" is a polite request.', '"你能开下窗户吗?"是一个礼貌的请求。', 'Languages Around the World', 38, 0, 'senior', 'wordlist', 'required1', 'U5', 'a polite request', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'depend', 'v.', '/dɪˈpend/', '依靠;取决于', 'How polite to be depends on who you are talking to.', '该多礼貌取决于你在和谁说话。', 'Languages Around the World', 39, 0, 'senior', 'wordlist', 'required1', 'U5', 'depend on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'record', 'v.', '/rɪˈkɔːd/', '录(音);记录', 'Sometimes I record my voice to compare my pronunciation.', '有时我录下自己的声音来比较发音。', 'Languages Around the World', 40, 0, 'senior', 'wordlist', 'required1', 'U5', 'record my voice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'trouble', 'n.', '/ˈtrʌbl/', '困难;麻烦', 'I''m having a lot of trouble with my listening.', '我的听力遇到了很多困难。', 'Languages Around the World', 41, 0, 'senior', 'wordlist', 'required1', 'U5', 'have trouble with', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'foreign', 'adj.', '/ˈfɒrən/', '外国的;外来的', 'There are many reasons why people learn a foreign language.', '人们学外语有许多原因。', 'Languages Around the World', 42, 0, 'senior', 'wordlist', 'required1', 'U5', 'a foreign language', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'history', 'n.', '/ˈhɪstri/', '历史;历程', 'The civilisation continued despite the ups and downs in its history.', '尽管历史几经起伏,这一文明仍延续下来。', 'Languages Around the World', 43, 0, 'senior', 'wordlist', 'required1', 'U5', 'through history', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'connect', 'v.', '/kəˈnekt/', '连接;联系', 'Written Chinese connects the present with the past.', '汉字把现在与过去连接起来。', 'Languages Around the World', 44, 0, 'senior', 'wordlist', 'required1', 'U5', 'connect the past and present', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.01', '①when(时间先行词 = on/in/at which)', 'A2', 10, '必修一 U5 — 先行词表时间(day/time/year/moment 等)、从句不缺主语或宾语(只缺时间状语)时,用关系副词 when(= 介词+which)。', 1, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.02', '②where(地点先行词 = in/at/on which)', 'A2', 10, '必修一 U5 — 先行词表地点(place/country/city/room 等)、从句只缺地点状语时,用关系副词 where(= 介词+which)。', 2, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.03', '③why(原因)+ 关系副词 vs 关系代词判断', 'A2', 10, '必修一 U5 — 先行词为 reason、从句缺原因状语时用 why;但若从句缺主语/宾语,即使先行词表时间/地点也要用关系代词 that/which;介词后只能用 which。', 3, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U5' AND code='u5.01'), '"I still remember the day ____ I first wrote a Chinese character."', 'when', 'which', 'where', 'that', 'A', '先行词 day 表时间,从句不缺主宾(只缺时间状语)→ when。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U5' AND code='u5.01'), '"There was a time ____ people in China were divided by dialects."', 'which', 'when', 'where', 'that', 'B', '先行词 time、从句完整 → when。', 2, 2, 'mcq');
