INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U5' AND code='u5.03'), '"The brush with ____ calligraphy is done must be held correctly."', 'that', 'when', 'where', 'which', 'D', '介词 with 后指物用 which。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Chinese Writing System', 'China is widely known for its ancient civilisation, which has continued into modern times despite the many ups and downs in its history. There are many reasons why this has been possible, but one of the main factors has been the Chinese writing system. At the beginning, written Chinese was a picture-based language. It dates back thousands of years to symbols carved on animal bones and shells. By the Shang Dynasty, these symbols had become a well-developed writing system. Over time, the system developed into different forms, and many varieties of characters appeared. This changed under Emperor Qinshihuang of the Qin Dynasty, who united the seven major states into one country where the writing system began to develop in one direction. That writing system was of great importance in uniting the Chinese people and culture.', '说明·汉字书写系统', 135, '[{"q":"According to the text, what has helped Chinese civilisation continue?","answer":"A","options":["Mainly the Chinese writing system.","Only its large population.","The weather of the country.","Foreign trade alone."],"explanation":"原文 ''one of the main factors has been the Chinese writing system'' 的转述。"},{"q":"What was written Chinese like at the very beginning?","answer":"B","options":["It was based on sounds.","It was a picture-based language.","It had no symbols at all.","It was the same as today''s hanzi."],"explanation":"原文 ''written Chinese was a picture-based language''(中段)。"},{"q":"What did Emperor Qinshihuang do for the writing system?","answer":"A","options":["He united the country so it developed in one direction.","He removed all characters.","He made it picture-based again.","He banned the use of writing."],"explanation":"末段 ''united the seven major states… develop in one direction'' 的转述。"}]'::jsonb, '[{"word":"civilisation","cn":"文明"},{"word":"system","cn":"体系;系统"},{"word":"unify","cn":"统一"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Art of Chinese Calligraphy', 'Written Chinese has become an important means by which China''s present is connected with its past. People today can read the classic works that were written in ancient times. The high regard for the writing system can be seen in the development of Chinese characters as an art form, known as Chinese calligraphy. Calligraphy is not only a beautiful art done with a brush, but also a way of showing the character of the person behind the brush. It is difficult to say exactly when calligraphy began, but it dates back at least to the Han Dynasty. Today, anyone from small children to old people can enjoy practising this art. As China plays a greater role in global affairs, an increasing number of international students are beginning to appreciate Chinese culture through this amazing language.', '说明·中国书法', 135, '[{"q":"What can people today still read, thanks to the writing system?","answer":"B","options":["Only modern newspapers.","The classic works written long ago.","Pictures with no words.","Nothing from the past."],"explanation":"原文 ''read the classic works that were written in ancient times'' 的转述。"},{"q":"Besides being beautiful, what does calligraphy show?","answer":"C","options":["The price of the brush.","The weather of the day.","The personality of the writer holding the brush.","The age of the paper."],"explanation":"原文 ''a way of showing the character of the person behind the brush''(中段)。"},{"q":"Why are more international students appreciating Chinese culture?","answer":"D","options":["Because Chinese is easy to spell.","Because calligraphy is free.","Because no one studies English now.","Because China is becoming more important in the world."],"explanation":"末句 ''As China plays a greater role in global affairs…'' 的转述。"}]'::jsonb, '[{"word":"calligraphy","cn":"书法"},{"word":"classic","cn":"经典的"},{"word":"appreciate","cn":"欣赏"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why Learn a Foreign Language', 'There are about seven thousand languages in the world, but only a few are spoken by very large numbers of people. Chinese and English have the most speakers, and the official languages of the United Nations are spoken by around 2.8 billion people as a native or second language. So why do so many students study a foreign language? Some think it means better job chances in the future. Others want to enjoy films, music or books in their original language. A few simply love the sound of a language and want to travel to the countries where it is spoken. Whatever the reason, learning a new language opens a door to a different way of thinking. It lets you see the world from another point of view, and that, many believe, is worth all the hard work.', '议论·为何学外语', 138, '[{"q":"How many languages are there in the world, according to the text?","answer":"A","options":["About seven thousand.","Only a few hundred.","Exactly 2.8 billion.","Just two."],"explanation":"原文 ''about seven thousand languages in the world'' 的转述。"},{"q":"Why do some students learn a foreign language?","answer":"B","options":["To forget their own language.","Because it may improve their future job prospects.","Because they are forced to.","To avoid travelling abroad."],"explanation":"原文 ''better job chances in the future''(中段,众多原因之一)。"},{"q":"What does the writer say learning a language gives you?","answer":"C","options":["Less free time.","A worse memory.","A new way of seeing the world.","Fewer friends."],"explanation":"末段 ''see the world from another point of view'' 的转述。"}]'::jsonb, '[{"word":"native","cn":"本地的;母语的"},{"word":"billion","cn":"十亿"},{"word":"point of view","cn":"观点"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'My Struggle with German', 'When I started studying German, it was a real struggle. The words felt strange on my tongue, and the grammar would not stay in my head. I told my mum that I wanted to give up. But she said that studying a language was not just for my future; it was exercise for the brain. The more I learned of a language, she said, the more my brain would grow. So I kept going. Then came the day when German suddenly no longer felt like a foreign language. I had finally reached a place where I could think in it and see the world from a different point of view. I could open a book and see meanings, not just a sea of words. That was when I finally understood the reason why my mum had encouraged me not to give up.', '记叙·学德语的奋斗', 142, '[{"q":"How did the writer feel when first studying German?","answer":"D","options":["It was very easy.","It was boring and useless.","It felt like a holiday.","It felt very difficult at first."],"explanation":"原文 ''it was a real struggle'' 的转述。"},{"q":"What did the writer''s mum compare language learning to?","answer":"A","options":["Exercise for the brain.","A waste of time.","A game with no rules.","A short holiday."],"explanation":"原文 ''it was exercise for the brain''(中段)。"},{"q":"What finally happened after the writer kept going?","answer":"B","options":["The writer gave up completely.","The writer could think in German and see meanings.","German became harder than ever.","The mum stopped helping."],"explanation":"末段 ''could think in it… see meanings, not just a sea of words'' 的转述。"}]'::jsonb, '[{"word":"struggle","cn":"艰难;奋斗"},{"word":"tongue","cn":"舌头;语言"},{"word":"attitude","cn":"态度"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Two Kinds of English', 'English is not exactly the same everywhere. British English and American English use different words for the same things. For example, what British people call petrol, Americans call gas; the British underground is the American subway; a British flat is an American apartment. Sometimes these differences can cause funny misunderstandings. A Chinese student once told his British friend that he wanted to buy some pants. In American English, pants means trousers, but in British English the same word means underwear. They both laughed when they understood the mix-up. These differences are not mistakes; they are just two ways of speaking the same language. If you are not sure which word someone means, it is always polite to ask, "Sorry, what do you mean by that?"', '说明·英美英语差异', 125, '[{"q":"What is the British word for the American ''gas''?","answer":"C","options":["Subway.","Apartment.","Petrol.","Underground."],"explanation":"原文 ''what British people call petrol, Americans call gas''。"},{"q":"Why did the two friends laugh?","answer":"D","options":["Because the student spoke no English.","Because they could not find a shop.","Because the word did not exist.","Because ''pants'' means different things in the two kinds of English."],"explanation":"原文 ''pants means trousers… means underwear… laughed when they understood''(中段)。"},{"q":"What does the writer suggest doing when you are unsure of a word?","answer":"A","options":["Politely ask what the person means.","Stop speaking English.","Guess and say nothing.","Use only Chinese."],"explanation":"末句 ''it is always polite to ask…'' 的转述。"}]'::jsonb, '[{"word":"dialect","cn":"方言"},{"word":"apartment","cn":"公寓"},{"word":"polite","cn":"礼貌的"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Help with Learning English', 'On an online forum, Chinese students share their biggest problems with learning English. Wang Le says he used to get high marks but now has trouble with listening; when native speakers talk fast, he can catch only a few words. Jia Xin advises listening to English radio programmes to get used to the speed, and even recording your own voice to compare your pronunciation with the host''s. Jia Xin''s own headache is being polite: it is easy to say "Open the window", but harder to choose between "Open the window, please" and "Would you mind opening the window?" Li Rui explains that the right choice depends on who you are talking to. With a close friend, a few short words are enough; with someone you do not know well, a longer and more polite question is better. For Li Rui, though, the biggest problem is simply remembering so many new words.', '应用·学英语困难与建议', 151, '[{"q":"What is Wang Le''s main problem with English now?","answer":"B","options":["He cannot read at all.","He has trouble with listening.","He forgets how to write.","He dislikes English films."],"explanation":"原文 ''now has trouble with listening'' 的转述。"},{"q":"What does Jia Xin advise doing to improve listening?","answer":"C","options":["Stop listening to English.","Only read silently.","Listen to English radio and record your own voice.","Speak Chinese more often."],"explanation":"原文 ''listening to English radio programmes… recording your own voice''(中段)。"},{"q":"According to Li Rui, what does being polite in English depend on?","answer":"D","options":["The time of day.","The weather.","How loud you speak.","The person you are speaking with."],"explanation":"原文 ''the right choice depends on who you are talking to''(后段)。"}]'::jsonb, '[{"word":"advice","cn":"建议"},{"word":"trouble","cn":"困难"},{"word":"depend","cn":"取决于"}]'::jsonb, 2, 'required1', 'U5');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'Learning to Write Chinese', 'When I first started learning Chinese, the characters looked like tiny pictures that I could not (1)____. My teacher told me that each character is a (2)____ with its own meaning and story. She said that written Chinese (3)____ back thousands of years to symbols carved on bones. At first it was a real (4)____, and the strokes felt strange on my hand. But slowly I began to (5)____ how beautiful the writing was. I learned that people who speak different (6)____ across China can still read the same characters. That is the (7)____ why written Chinese has helped to (8)____ the country for so long. Now I practise a few characters every (9)____, and each one feels like a small window into an ancient (10)____. Learning to write Chinese has changed the way I see the world.', 138, 2, '[{"q":"1","answer":"A","options":["read","eat","buy","throw"],"explanation":"could not read 看不懂。"},{"q":"2","answer":"B","options":["price","symbol","noise","season"],"explanation":"a symbol 一个符号。"},{"q":"3","answer":"C","options":["looks","gives","dates","puts"],"explanation":"date back 追溯到。"},{"q":"4","answer":"D","options":["holiday","game","joke","struggle"],"explanation":"a real struggle 一种艰难。"},{"q":"5","answer":"A","options":["appreciate","forget","waste","lose"],"explanation":"appreciate 欣赏。"},{"q":"6","answer":"B","options":["foods","dialects","songs","games"],"explanation":"different dialects 不同方言。"},{"q":"7","answer":"C","options":["price","noise","reason","weather"],"explanation":"the reason why 原因。"},{"q":"8","answer":"D","options":["break","leave","sell","unify"],"explanation":"unify the country 统一国家。"},{"q":"9","answer":"A","options":["day","year","century","never"],"explanation":"every day 每天。"},{"q":"10","answer":"B","options":["machine","civilisation","market","garden"],"explanation":"ancient civilisation 古老文明。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'The Story of a Character', 'Many Chinese characters began as simple (1)____ of real things. Long ago, ancient people (2)____ marks onto animal bones and shells to record their lives. The character for ''horse'', for example, once looked like a real horse with four (3)____ and a tail. Over the (4)____, the picture slowly became simpler, until it turned into the character we (5)____ today. This is one (6)____ why Chinese is such an interesting language to learn: behind each character there is often a small (7)____. By the Shang Dynasty, these pictures had developed into a complete writing (8)____. Even now, some of the ancient (9)____ can still be seen inside modern characters. Learning where a character comes from makes it much easier to (10)____.', 121, 2, '[{"q":"1","answer":"C","options":["prices","noises","pictures","machines"],"explanation":"pictures of real things 实物的图画。"},{"q":"2","answer":"D","options":["sold","ate","lost","carved"],"explanation":"carved marks 刻下记号。"},{"q":"3","answer":"A","options":["legs","books","wheels","wings"],"explanation":"four legs 四条腿。"},{"q":"4","answer":"B","options":["minutes","years","seconds","metres"],"explanation":"over the years 多年间。"},{"q":"5","answer":"C","options":["buy","drop","use","hide"],"explanation":"the character we use 我们使用的字。"},{"q":"6","answer":"D","options":["price","shop","city","reason"],"explanation":"one reason why 一个原因。"},{"q":"7","answer":"A","options":["story","price","noise","error"],"explanation":"a small story 一个小故事。"},{"q":"8","answer":"B","options":["machine","system","garden","market"],"explanation":"writing system 书写系统。"},{"q":"9","answer":"C","options":["songs","prices","symbols","tickets"],"explanation":"ancient symbols 古老符号。"},{"q":"10","answer":"D","options":["forget","lose","sell","remember"],"explanation":"easier to remember 更容易记住。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'Why I Love Calligraphy', 'My grandfather is the person (1)____ first showed me Chinese calligraphy. He told me it is an (2)____ form done with a soft brush. At first my lines were shaky and ugly, and I almost wanted to give (3)____. But Grandpa said that calligraphy shows the (4)____ of the person behind the brush, so I should be patient. Little by little, I learned to hold the brush correctly and to (5)____ each stroke slowly. Now calligraphy is the hobby (6)____ I enjoy most. It makes me feel (7)____ and helps me forget the stress of school. It also (8)____ me to the past, because people have practised this art for thousands of (9)____. Whenever I pick up my brush, I feel proud to be part of such an ancient (10)____.', 130, 2, '[{"q":"1","answer":"A","options":["who","which","where","when"],"explanation":"the person who 指人作主语。"},{"q":"2","answer":"B","options":["exam","art","error","event"],"explanation":"an art form 一种艺术形式。"},{"q":"3","answer":"C","options":["in","off","up","out"],"explanation":"give up 放弃。"},{"q":"4","answer":"D","options":["price","weather","noise","character"],"explanation":"the character of the person 人的品格。"},{"q":"5","answer":"A","options":["draw","throw","sell","lose"],"explanation":"draw each stroke 画好每一笔。"},{"q":"6","answer":"B","options":["who","that","where","when"],"explanation":"the hobby that I enjoy 指物作宾语。"},{"q":"7","answer":"C","options":["angry","afraid","calm","bored"],"explanation":"feel calm 感到平静。"},{"q":"8","answer":"D","options":["sells","breaks","loses","connects"],"explanation":"connects me to the past 把我和过去相连。"},{"q":"9","answer":"A","options":["years","minutes","metres","seconds"],"explanation":"thousands of years 数千年。"},{"q":"10","answer":"B","options":["shop","art","game","city"],"explanation":"an ancient art 古老的艺术。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'A Funny Misunderstanding', 'Last week my American friend Tom and I had a funny (1)____. I told him I needed to buy some ''pants'', and he started to (2)____. In American English, ''pants'' means trousers, but I had learned the (3)____ in British English, where it means underwear! When we finally (4)____ the mix-up, we both laughed. Tom explained that British and American English often use different (5)____ for the same thing. For example, the British say ''petrol'' while Americans say ''gas'', and a British ''flat'' is an American (6)____. These are not (7)____; they are just two ways of speaking the same (8)____. Now, whenever I am not (9)____ what someone means, I simply ask, "Sorry, what do you mean by that?" Being willing to (10)____ has saved me from many funny mistakes.', 131, 2, '[{"q":"1","answer":"C","options":["holiday","machine","misunderstanding","market"],"explanation":"a funny misunderstanding 有趣的误会。"},{"q":"2","answer":"D","options":["cry","sleep","leave","laugh"],"explanation":"start to laugh 开始笑。"},{"q":"3","answer":"A","options":["word","price","song","game"],"explanation":"learned the word 学的词。"},{"q":"4","answer":"B","options":["forgot","understood","sold","lost"],"explanation":"understood the mix-up 弄懂误会。"},{"q":"5","answer":"C","options":["prices","noises","words","tickets"],"explanation":"different words 不同的词。"},{"q":"6","answer":"D","options":["garden","stadium","castle","apartment"],"explanation":"American apartment 美式公寓。"},{"q":"7","answer":"A","options":["mistakes","songs","prices","games"],"explanation":"not mistakes 不是错误。"},{"q":"8","answer":"B","options":["food","language","city","machine"],"explanation":"the same language 同一种语言。"},{"q":"9","answer":"C","options":["rich","late","sure","busy"],"explanation":"not sure 不确定。"},{"q":"10","answer":"D","options":["hide","forget","leave","ask"],"explanation":"willing to ask 愿意询问。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'Improving My Spoken English', 'My biggest (1)____ with English used to be speaking politely. It is easy to say "Open the window", but in English that can sound quite (2)____. So I had to learn to (3)____ between "Open the window, please" and "Would you mind opening the window?" My friend Li Rui told me that the right choice (4)____ on who you are talking to. With a close friend, a few short words are (5)____; but with someone you do not know well, a longer, more polite (6)____ is better. To practise, I listen to English radio every day to get (7)____ to how fast native speakers talk. Sometimes I even (8)____ my own voice and compare it with the host''s. Step by step, my speaking has (9)____, and I feel much more (10)____ when I talk to foreign visitors now.', 138, 2, '[{"q":"1","answer":"A","options":["trouble","song","price","game"],"explanation":"biggest trouble 最大困难。"},{"q":"2","answer":"B","options":["polite","rude","happy","quiet"],"explanation":"sound rude 听起来无礼。"},{"q":"3","answer":"C","options":["sleep","sell","choose","lose"],"explanation":"choose between 在……之间选择。"},{"q":"4","answer":"D","options":["sells","breaks","leaves","depends"],"explanation":"depends on 取决于。"},{"q":"5","answer":"A","options":["enough","wrong","empty","late"],"explanation":"are enough 就够了。"},{"q":"6","answer":"B","options":["noise","request","price","game"],"explanation":"a polite request 礼貌的请求。"},{"q":"7","answer":"C","options":["lost","afraid","used","tired"],"explanation":"get used to 习惯于。"},{"q":"8","answer":"D","options":["throw","sell","hide","record"],"explanation":"record my own voice 录下声音。"},{"q":"9","answer":"A","options":["improved","stopped","failed","disappeared"],"explanation":"has improved 提高了。"},{"q":"10","answer":"B","options":["afraid","confident","bored","sorry"],"explanation":"more confident 更自信。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U5', 'How Writing United China', 'Long ago, China was a land (1)____ people were divided by mountains and rivers. Different regions spoke different (2)____, and they could not easily understand one another''s speech. However, there was one thing they (3)____: their written characters. No matter (4)____ a person lived, the same character carried the same (5)____. This is the main reason (6)____ written Chinese became so important. When Emperor Qinshihuang (7)____ the country, he made the writing system develop in one (8)____, which helped to bring the people together. Even today, written Chinese is a (9)____ by which the past and the present are connected. People can still read works that were (10)____ thousands of years ago, and in this way the long story of Chinese culture continues.', 123, 2, '[{"q":"1","answer":"C","options":["which","when","where","why"],"explanation":"a land where 地点先行词用 where。"},{"q":"2","answer":"D","options":["foods","songs","games","dialects"],"explanation":"different dialects 不同方言。"},{"q":"3","answer":"A","options":["shared","lost","sold","broke"],"explanation":"one thing they shared 共有的。"},{"q":"4","answer":"B","options":["what","where","who","which"],"explanation":"no matter where 不论在哪里。"},{"q":"5","answer":"C","options":["price","noise","meaning","weather"],"explanation":"the same meaning 相同的意义。"},{"q":"6","answer":"D","options":["which","where","when","why"],"explanation":"the reason why 原因。"},{"q":"7","answer":"A","options":["unified","left","sold","lost"],"explanation":"unified the country 统一国家。"},{"q":"8","answer":"B","options":["garden","direction","market","machine"],"explanation":"in one direction 朝一个方向。"},{"q":"9","answer":"C","options":["price","noise","means","game"],"explanation":"a means by which 一种途径。"},{"q":"10","answer":"D","options":["eaten","sold","thrown","written"],"explanation":"works that were written 被写下的作品。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Which Language to Learn', '必修一 U5 · dialogue', 3, 'Amy: What foreign language do you want to study, Ben?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 Languages of the World', '必修一 U5 · passage', 2, 'There are about seven thousand languages in the world today.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 A Word with Two Meanings', '必修一 U5 · dialogue', 3, 'Zhou Wei: I really need to buy some pants today.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 The Chinese Writing System', '必修一 U5 · passage', 2, 'Written Chinese began thousands of years ago as simple pictures.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Advice on Learning English', '必修一 U5 · dialogue', 3, 'Wang Le: I have so much trouble with my listening. Any advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 A Tip for Language Learners', '必修一 U5 · passage', 2, 'Here is a simple tip for anyone learning a new language.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Blog about English Study(写一篇英语学习博客)', 'A Travel Email', '假设你叫李华,你常逛一个中国学生学英语的论坛。请用英语写一篇约80词的博客,内容包括:① 清楚描述你在学英语时遇到的一个困难(如听力/口语礼貌/词汇);② 给出一两条解决这个困难的方法;③ 鼓励有同样困难的同学。注意:每句都要围绕中心、用代词正确指代。', 'Suppose you are Li Hua. You often visit a forum where Chinese students discuss learning English. Write a blog (about 80 words) including: 1) a clear description of one problem you have in learning English (e.g. listening, being polite, vocabulary); 2) one or two ways to solve it; 3) some encouragement for classmates with the same problem.', '["清楚描述困难(My biggest problem is … / I have trouble with …)","解决方法(One thing that works for me is … / You might try …)","鼓励同学(Don''t give up — it gets easier!)","每句围绕中心、代词指代清楚"]'::jsonb, 70, 100, 'Hi everyone! My biggest problem in learning English is listening. When native speakers talk fast, I can catch only a few words and miss the main idea. One thing that really works for me is listening to English radio every day, so I get used to the speed. I also record my own voice and compare it with the speaker''s, which helps me hear my mistakes. If you have the same problem, don''t give up — little by little, it gets much easier. We can all improve together!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My biggest problem in learning English is listening.","One thing that really works for me is listening to English radio every day.","I record my own voice and compare it with the speaker''s, which helps me hear my mistakes.","Little by little, it gets much easier."]'::jsonb, '[{"wrong":"I have trouble in listening.","correct":"I have trouble with listening.","note":"have trouble with sth 固定搭配。"},{"wrong":"The radio help me a lot.","correct":"The radio helps me a lot.","note":"主语第三人称单数,动词加 s。"},{"wrong":"It is a way which I can improve.","correct":"It is a way in which I can improve.","note":"way 后从句缺方式状语,用 in which / that / 省略。"}]'::jsonb, '【英语学习博客结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required1', 'U5', '{"title":"限制性定语从句·关系副词 when / where / why 速查","intro":"关系副词在从句中作状语(时间/地点/原因),等于「介词+which」。判断口诀:从句缺状语→用关系副词,缺主语/宾语→用关系代词 that/which。","table":{"headers":["关系副词","用法 / 例句 / 等价"],"rows":[["when","时间先行词(day/time/year):the day when = on/in which"],["where","地点先行词(place/country/room):the place where = in/at which"],["why","原因(reason):the reason why = for which"],["介词+which","从句缺主宾、或表达更正式:on which / in which / by which"]]},"specialRules":[{"rule":"从句只缺状语(时间/地点/原因)→ 才用关系副词","mark":"the day when I arrived(缺时间状语)"},{"rule":"从句缺主语/宾语 → 即使先行词是时间/地点也用 that/which","mark":"the day that changed my life(缺主语→that)"},{"rule":"the day when = on/in which;the place where = in/at which;the reason why = for which","mark":"等价替换"},{"rule":"介词后只能用 which,不可用 that","mark":"on which √ / on that ×"}],"why":["关系副词 = 介词 + which,在从句里充当状语,所以从句的主语、宾语都不缺;一旦主语或宾语缺了,就要换成关系代词 that/which。"],"gaokaoPoints":["when/where/why 与 which/that 的判断(看从句缺什么成分);介词+which;语法填空高频。","the way 后的定语从句:用 that / in which / 或省略,但不用 which 单独引导。"],"examVsReal":[{"exam":"the house where I live（考试/书面）","real":"the house I live in","note":"考试用 where;口语常省略关系词、把介词放句末"},{"exam":"the reason why he gave up（考试）","real":"the reason he gave up / the reason that he gave up","note":"考试用 why;口语里 why 常被省略或用 that"}]}'::jsonb);
